//! Ruby values to `serde_json::Value` and back, in Rust. Generated by everything-rust.

// Ports without dynamic values use only some of these.
#![allow(dead_code)]

use magnus::{Float, Integer, RArray, RHash, RString, Ruby, Symbol, value::ReprValue};
use serde_json::{Map, Value, json};

/// A Ruby value as JSON.
pub fn from_rb(v: magnus::Value) -> Result<Value, String> {
    let ruby = Ruby::get().map_err(|e| e.to_string())?;
    if v.is_nil() {
        return Ok(Value::Null);
    }
    if v.is_kind_of(ruby.class_true_class()) {
        return Ok(Value::Bool(true));
    }
    if v.is_kind_of(ruby.class_false_class()) {
        return Ok(Value::Bool(false));
    }
    if let Some(i) = Integer::from_value(v) {
        return Ok(match i.to_i64() {
            Ok(n) => json!(n),
            Err(_) => {
                json!({"$int": v.funcall::<_, _, String>("to_s", ()).map_err(|e| e.to_string())?})
            }
        });
    }
    if let Some(f) = Float::from_value(v) {
        let x = f.to_f64();
        return Ok(if x.is_nan() {
            json!({"$num": "NaN"})
        } else if x.is_infinite() {
            json!({"$num": if x > 0.0 { "Infinity" } else { "-Infinity" }})
        } else if x == 0.0 && x.is_sign_negative() {
            json!({"$num": "-0"})
        } else {
            json!(x)
        });
    }
    if let Some(s) = RString::from_value(v) {
        return s.to_string().map(Value::String).map_err(|e| e.to_string());
    }
    if let Some(s) = Symbol::from_value(v) {
        return Ok(json!({"$sym": s.name().map_err(|e| e.to_string())?}));
    }
    if let Some(a) = RArray::from_value(v) {
        let mut out = Vec::with_capacity(a.len());
        for item in a.into_iter() {
            out.push(from_rb(item)?);
        }
        return Ok(Value::Array(out));
    }
    if let Some(h) = RHash::from_value(v) {
        let mut map = Map::new();
        let mut pairs = Vec::new();
        let mut string_keys = true;
        h.foreach(|k: magnus::Value, x: magnus::Value| {
            let value =
                from_rb(x).map_err(|e| magnus::Error::new(ruby.exception_type_error(), e))?;
            match RString::from_value(k) {
                Some(s) => {
                    let key = s.to_string()?;
                    pairs.push(json!([key.clone(), value.clone()]));
                    map.insert(key, value);
                }
                None => {
                    string_keys = false;
                    let key = from_rb(k)
                        .map_err(|e| magnus::Error::new(ruby.exception_type_error(), e))?;
                    pairs.push(json!([key, value]));
                }
            }
            Ok(magnus::r_hash::ForEach::Continue)
        })
        .map_err(|e| e.to_string())?;
        return Ok(if string_keys {
            Value::Object(map)
        } else {
            json!({"$hash": pairs})
        });
    }
    Err(format!(
        "TypeError: unsupported argument {}",
        v.class().inspect()
    ))
}

/// A Ruby argument as the port's parameter type.
pub fn arg<T: serde::de::DeserializeOwned>(v: magnus::Value) -> Result<T, String> {
    serde_json::from_value(from_rb(v)?).map_err(|e| format!("TypeError: {e}"))
}

/// A port result as a Ruby value.
pub fn to_rb<T: serde::Serialize>(ruby: &Ruby, out: &T) -> Result<magnus::Value, magnus::Error> {
    let value = serde_json::to_value(out)
        .map_err(|e| magnus::Error::new(ruby.exception_type_error(), e.to_string()))?;
    value_to_rb(ruby, &value)
}

fn value_to_rb(ruby: &Ruby, v: &Value) -> Result<magnus::Value, magnus::Error> {
    Ok(match v {
        Value::Null => ruby.qnil().as_value(),
        Value::Bool(true) => ruby.qtrue().as_value(),
        Value::Bool(false) => ruby.qfalse().as_value(),
        Value::Number(n) => match n.as_i64() {
            Some(i) if !n.is_f64() => ruby.integer_from_i64(i).as_value(),
            _ => ruby
                .float_from_f64(n.as_f64().unwrap_or(f64::NAN))
                .as_value(),
        },
        Value::String(s) => ruby.str_new(s).as_value(),
        Value::Array(items) => {
            let array = ruby.ary_new_capa(items.len());
            for item in items {
                array.push(value_to_rb(ruby, item)?)?;
            }
            array.as_value()
        }
        Value::Object(o) if o.len() == 1 && o.keys().next().is_some_and(|k| k.starts_with('$')) => {
            let (key, inner) = o.iter().next().expect("one entry");
            match key.as_str() {
                "$num" => ruby
                    .float_from_f64(match inner.as_str() {
                        Some("Infinity") => f64::INFINITY,
                        Some("-Infinity") => f64::NEG_INFINITY,
                        Some("-0") => -0.0,
                        _ => f64::NAN,
                    })
                    .as_value(),
                "$sym" => ruby
                    .to_symbol(inner.as_str().unwrap_or_default())
                    .as_value(),
                "$int" => ruby
                    .str_new(inner.as_str().unwrap_or("0"))
                    .funcall("to_i", ())?,
                "$hash" => {
                    let hash = ruby.hash_new();
                    for pair in inner.as_array().map(Vec::as_slice).unwrap_or_default() {
                        if let Some([k, x]) = pair.as_array().map(Vec::as_slice) {
                            hash.aset(value_to_rb(ruby, k)?, value_to_rb(ruby, x)?)?;
                        }
                    }
                    hash.as_value()
                }
                _ => {
                    let hash = ruby.hash_new();
                    hash.aset(ruby.str_new(key), value_to_rb(ruby, inner)?)?;
                    hash.as_value()
                }
            }
        }
        Value::Object(o) => {
            let hash = ruby.hash_new();
            for (k, x) in o {
                hash.aset(ruby.str_new(k), value_to_rb(ruby, x)?)?;
            }
            hash.as_value()
        }
    })
}
